from pathlib import Path

path = Path('admin.html')
text = path.read_text(encoding='utf-8')

if 'id="nav-card-quota"' in text:
    print('admin card quota UI already present')
else:
    nav_anchor = '''          <a href="#" onclick="switchTab('cards')" id="nav-cards" class="nav-item flex items-center px-4 py-3 rounded-xl text-sm font-bold">\n            <span class="material-symbols-outlined mr-3 text-[20px]">badge</span>\n            全站名片庫\n          </a>'''
    nav_insert = nav_anchor + '''\n          <a href="#" onclick="switchTab('card-quota')" id="nav-card-quota" class="nav-item flex items-center px-4 py-3 rounded-xl text-sm font-bold">\n            <span class="material-symbols-outlined mr-3 text-[20px]">tune</span>\n            名片額度設定\n          </a>'''
    if nav_anchor not in text:
        raise SystemExit('nav anchor not found')
    text = text.replace(nav_anchor, nav_insert, 1)

    tab_anchor = '      <!-- Tab: Cards -->\n      <div id="tab-cards" class="tab-content hidden space-y-6">'
    quota_tab = '''      <!-- Tab: Card Quota -->\n      <div id="tab-card-quota" class="tab-content hidden space-y-6">\n        <section class="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">\n          <div class="px-6 py-5 border-b border-slate-100">\n            <div class="flex items-center gap-3">\n              <span class="material-symbols-outlined text-blue-600 text-[26px]">tune</span>\n              <div>\n                <h3 class="text-xl font-black text-slate-900">名片收藏額度設定</h3>\n                <p class="text-sm font-bold text-slate-500 mt-1">一般免費會員適用。留空＝不限制；0＝禁止使用。</p>\n              </div>\n            </div>\n          </div>\n          <div class="p-6 space-y-6">\n            <div class="rounded-2xl border border-blue-100 bg-blue-50/50 p-5">\n              <div class="flex items-center justify-between gap-3 mb-4">\n                <div>\n                  <div class="text-base font-black text-slate-900">免費方案</div>\n                  <div class="text-xs font-bold text-slate-500 mt-1">適用 user；admin / tenant / store 維持無限制。</div>\n                </div>\n                <span class="px-3 py-1 rounded-full bg-blue-600 text-white text-xs font-black">啟用中</span>\n              </div>\n              <div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n                <label class="block">\n                  <span class="block text-sm font-black text-slate-700 mb-2">每日上限</span>\n                  <div class="flex items-center gap-2">\n                    <input id="admin-card-quota-free-daily" type="number" min="0" step="1" inputmode="numeric" placeholder="留空＝不限制" class="w-full border border-slate-200 bg-white rounded-xl px-4 py-3 text-base font-bold text-slate-900 outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400">\n                    <span class="text-sm font-black text-slate-400 whitespace-nowrap">張／日</span>\n                  </div>\n                </label>\n                <label class="block">\n                  <span class="block text-sm font-black text-slate-700 mb-2">個人總上限</span>\n                  <div class="flex items-center gap-2">\n                    <input id="admin-card-quota-free-total" type="number" min="0" step="1" inputmode="numeric" placeholder="留空＝不限制" class="w-full border border-slate-200 bg-white rounded-xl px-4 py-3 text-base font-bold text-slate-900 outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400">\n                    <span class="text-sm font-black text-slate-400 whitespace-nowrap">張</span>\n                  </div>\n                </label>\n              </div>\n            </div>\n            <div class="rounded-2xl border border-dashed border-slate-200 bg-slate-50 p-5">\n              <div class="flex items-center justify-between gap-3 mb-4">\n                <div>\n                  <div class="text-base font-black text-slate-500">收費方案</div>\n                  <div class="text-xs font-bold text-slate-400 mt-1">欄位預留，暫不啟用。</div>\n                </div>\n                <span class="px-3 py-1 rounded-full bg-slate-200 text-slate-500 text-xs font-black">預留・未啟用</span>\n              </div>\n              <div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n                <label class="block"><span class="block text-sm font-black text-slate-400 mb-2">每日上限</span><input type="number" disabled placeholder="尚未設定" class="w-full border border-slate-200 bg-slate-100 rounded-xl px-4 py-3 text-base font-bold text-slate-400 cursor-not-allowed"></label>\n                <label class="block"><span class="block text-sm font-black text-slate-400 mb-2">個人總上限</span><input type="number" disabled placeholder="尚未設定" class="w-full border border-slate-200 bg-slate-100 rounded-xl px-4 py-3 text-base font-bold text-slate-400 cursor-not-allowed"></label>\n              </div>\n            </div>\n            <div id="admin-card-quota-status" class="rounded-xl border border-slate-100 bg-slate-50 px-4 py-3 text-sm font-bold text-slate-500">尚未載入設定。</div>\n            <div class="flex justify-end gap-3">\n              <button type="button" onclick="loadAdminCardQuotaSettings()" class="px-5 py-3 rounded-xl border border-slate-200 bg-white text-slate-700 text-sm font-black hover:bg-slate-50">重新載入</button>\n              <button id="btn-save-admin-card-quota" type="button" onclick="saveAdminCardQuotaSettings()" class="px-6 py-3 rounded-xl bg-blue-600 text-white text-sm font-black shadow-sm hover:bg-blue-700 active:scale-95 transition-transform flex items-center gap-2"><span class="material-symbols-outlined text-[18px]">save</span> 儲存額度</button>\n            </div>\n          </div>\n        </section>\n      </div>\n\n'''
    if tab_anchor not in text:
        raise SystemExit('tab anchor not found')
    text = text.replace(tab_anchor, quota_tab + tab_anchor, 1)

    switch_anchor = "      if (tabId === 'users') loadUsers();\n      if (tabId === 'cards') {"
    switch_insert = "      if (tabId === 'users') loadUsers();\n      if (tabId === 'card-quota') loadAdminCardQuotaSettings();\n      if (tabId === 'cards') {"
    if switch_anchor not in text:
        raise SystemExit('switch anchor not found')
    text = text.replace(switch_anchor, switch_insert, 1)

    fn_anchor = '    function switchTab(tabId) {'
    functions = '''    function adminQuotaValue(value) {\n      if (value === undefined || value === null || value === '') return '';\n      const n = Number(value);\n      return Number.isFinite(n) && n >= 0 ? String(Math.floor(n)) : '';\n    }\n\n    function setAdminCardQuotaStatus(message, isError = false) {\n      const el = document.getElementById('admin-card-quota-status');\n      if (!el) return;\n      el.textContent = message || '';\n      el.className = 'rounded-xl border px-4 py-3 text-sm font-bold ' + (isError ? 'border-red-100 bg-red-50 text-red-600' : 'border-slate-100 bg-slate-50 text-slate-500');\n    }\n\n    async function loadAdminCardQuotaSettings() {\n      setAdminCardQuotaStatus('讀取額度設定中...');\n      const res = await fetchAPI('getStoreSettings', { networkId: 'admin' }, { timeoutMs: 20000 });\n      if (!res) {\n        setAdminCardQuotaStatus('額度設定讀取失敗，請稍後重試。', true);\n        return;\n      }\n      const daily = document.getElementById('admin-card-quota-free-daily');\n      const total = document.getElementById('admin-card-quota-free-total');\n      if (daily) daily.value = adminQuotaValue(res.cardQuotaFreeDailyLimit);\n      if (total) total.value = adminQuotaValue(res.cardQuotaFreeTotalLimit);\n      setAdminCardQuotaStatus('設定已載入。留空代表不限制。');\n    }\n\n    async function saveAdminCardQuotaSettings() {\n      const button = document.getElementById('btn-save-admin-card-quota');\n      const daily = adminQuotaValue(document.getElementById('admin-card-quota-free-daily')?.value);\n      const total = adminQuotaValue(document.getElementById('admin-card-quota-free-total')?.value);\n      if (button) button.disabled = true;\n      setAdminCardQuotaStatus('儲存中...');\n      try {\n        const existing = await fetchAPI('getStoreSettings', { networkId: 'admin' }, { timeoutMs: 20000, silent: true }) || {};\n        const payload = {\n          ...existing,\n          networkId: 'admin',\n          cardQuotaFreeDailyLimit: daily,\n          cardQuotaFreeTotalLimit: total,\n          cardQuotaPaidDailyLimit: adminQuotaValue(existing.cardQuotaPaidDailyLimit),\n          cardQuotaPaidTotalLimit: adminQuotaValue(existing.cardQuotaPaidTotalLimit)\n        };\n        const saved = await fetchAPI('saveStoreSettings', payload, { timeoutMs: 20000 });\n        if (!saved) throw new Error('額度設定儲存失敗');\n        setAdminCardQuotaStatus('名片收藏額度已儲存。');\n        showToast('名片額度設定已儲存');\n      } catch (error) {\n        setAdminCardQuotaStatus(error.message || '額度設定儲存失敗', true);\n      } finally {\n        if (button) button.disabled = false;\n      }\n    }\n\n'''
    if fn_anchor not in text:
        raise SystemExit('function anchor not found')
    text = text.replace(fn_anchor, functions + fn_anchor, 1)

    path.write_text(text, encoding='utf-8')
    print('patched admin.html')

contract = Path('tools/check-admin-card-quota-contract.js')
contract.write_text("""const fs = require('fs');\nconst assert = require('assert');\nconst html = fs.readFileSync('admin.html', 'utf8');\nassert(html.includes('id=\\\"nav-card-quota\\\"'));\nassert(html.includes("switchTab('card-quota')"));\nassert(html.includes('id=\\\"tab-card-quota\\\"'));\nassert(html.includes('id=\\\"admin-card-quota-free-daily\\\"'));\nassert(html.includes('id=\\\"admin-card-quota-free-total\\\"'));\nassert(html.includes("fetchAPI('getStoreSettings'"));\nassert(html.includes("fetchAPI('saveStoreSettings'"));\nassert(html.includes('cardQuotaFreeDailyLimit'));\nassert(html.includes('cardQuotaFreeTotalLimit'));\nassert(html.includes("if (tabId === 'card-quota') loadAdminCardQuotaSettings();"));\nconsole.log('admin card quota UI contract passed.');\n""", encoding='utf-8')

runner = Path('tools/run-smoke-contracts.js')
r = runner.read_text(encoding='utf-8')
needle = "  'tools/check-card-quota-contract.js',\n"
if needle in r and "check-admin-card-quota-contract.js" not in r:
    r = r.replace(needle, needle + "  'tools/check-admin-card-quota-contract.js',\n")
elif "check-admin-card-quota-contract.js" not in r:
    raise SystemExit('smoke runner anchor not found')
runner.write_text(r, encoding='utf-8')
print('contract wired')
